import { useEffect, useMemo, useState } from "react";
import Header from "../Header/Header";
import VenueCard from "../VenueCard/venueCard";
import "./home.css";
import "../baseStyles.css";
import { auth, db } from "../../firebase";
import { collection, getDocs, query, where, doc, getDoc } from "firebase/firestore";

export default function Home() {
  const [venues, setVenues] = useState([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState("");

  const [city, setCity] = useState("");
  const [userLocation, setUserLocation] = useState(null);
  const [sortByDistance, setSortByDistance] = useState(false);

  const [search, setSearch] = useState("");
  const [foodCategory, setFoodCategory] = useState("");

  useEffect(() => {
    async function loadUserCityAndRestaurants() {
      setErr("");
      setLoading(true);

      try {
        const user = auth.currentUser;

        if (!user) {
          setErr("You must be logged in to view restaurants.");
          setVenues([]);
          return;
        }

        const userSnap = await getDoc(doc(db, "users", user.uid));

        if (!userSnap.exists()) {
          setErr("User profile not found.");
          setVenues([]);
          return;
        }

        const userData = userSnap.data();
        const selectedCity = userData?.cityId || "calgary";

        setCity(selectedCity);

        if (!selectedCity) {
          setErr("No city selected.");
          setVenues([]);
          return;
        }

        const q = query(
          collection(db, "restaurants"),
          where("cityId", "==", selectedCity)
        );

        const snap = await getDocs(q);
        const data = snap.docs.map((d) => ({ id: d.id, ...d.data() }));
        setVenues(data);
      } catch (e) {
        setErr(e?.message || "Failed to load restaurants.");
      } finally {
        setLoading(false);
      }
    }

    loadUserCityAndRestaurants();
  }, []);

  function getDistanceKm(lat1, lon1, lat2, lon2) {
    const toRad = (value) => (value * Math.PI) / 180;
    const earthRadiusKm = 6371;

    const dLat = toRad(lat2 - lat1);
    const dLon = toRad(lon2 - lon1);

    const a =
      Math.sin(dLat / 2) * Math.sin(dLat / 2) +
      Math.cos(toRad(lat1)) *
        Math.cos(toRad(lat2)) *
        Math.sin(dLon / 2) *
        Math.sin(dLon / 2);

    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return earthRadiusKm * c;
  }

  function handleNearMe() {
    if (sortByDistance) {
      setSortByDistance(false);
      setUserLocation(null);
      return;
    }

    if (!navigator.geolocation) {
      alert("Geolocation is not supported by your browser.");
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        setUserLocation({
          lat: position.coords.latitude,
          lng: position.coords.longitude,
        });
        setSortByDistance(true);
      },
      () => {
        alert("Could not get your location.");
      }
    );
  }

  const filtered = useMemo(() => {
    const s = search.trim().toLowerCase();

    let results = venues.filter((v) => {
      if (s && !(v.name || "").toLowerCase().includes(s)) return false;

      if (foodCategory && (v.foodCategory || "").toLowerCase() !== foodCategory) {
        return false;
      }

      return true;
    });

    if (sortByDistance && userLocation) {
      results = results
        .map((v) => {
          const lat = Number(v?.coordinates?.[0]);
          const lng = Number(v?.coordinates?.[1]);

          if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
            return { ...v, distanceKm: Number.POSITIVE_INFINITY };
          }

          const distanceKm = getDistanceKm(
            userLocation.lat,
            userLocation.lng,
            lat,
            lng
          );

          return {
            ...v,
            distanceKm,
          };
        })
        .sort((a, b) => a.distanceKm - b.distanceKm);
    } else {
      results = results.map((v) => {
        const { distanceKm, ...rest } = v;
        return rest;
      });
    }

    return results;
  }, [venues, search, foodCategory, sortByDistance, userLocation]);


  const cityTitle = city
    ? city.charAt(0).toUpperCase() + city.slice(1)
    : "";

  return (
    <>
      <Header />

      <section id="homeSection">
        <h1>{cityTitle ? `Restaurants in ${cityTitle}` : "Restaurants"}</h1>

        <div className="filterRow">
          <input
            className="searchInput"
            type="text"
            placeholder="Search restaurants..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />

          <select
            className="filterSelect"
            value={foodCategory}
            onChange={(e) => setFoodCategory(e.target.value)}
          >
            <option value="">All Categories</option>
            <option value="pub">Pub</option>
            <option value="pizza">Pizza</option>
            <option value="mexican">Mexican</option>
            <option value="asian">Asian</option>
            <option value="burger">Burger</option>
            <option value="cafe">Cafe</option>
          </select>

          <button
            type="button"
            className={sortByDistance ? "filterBtn active" : "filterBtn"}
            onClick={handleNearMe}
          >
            Near Me
          </button>

       
        </div>

        {loading ? (
          <p>Loading...</p>
        ) : err ? (
          <p className="errorText">{err}</p>
        ) : filtered.length === 0 ? (
          <p>No restaurants match your search/filters.</p>
        ) : (
          <div className="venueList">
            {filtered.map((v) => (
              <VenueCard key={v.id} venue={v} />
            ))}
          </div>
        )}
      </section>
    </>
  );
}